 d=json.loads(f.read_text())
 if 'exit_code' not in d:continue
 assert d['exit_code']==0
 name=f.parent.name
 if '-confirm-' not in name:
  group={}
  for task in sorted({t['name'] for t in d['tests']}):
   ts=[t for t in d['tests'] if t['name']==task];group[task]={k:statistics.mean(t[k] for t in ts) for k in ['pp_tps','tg_tps','wall_s']}
  log=(f.parent/'engine.log').read_text();rows=re.findall(r'ORNITH_LAYER .*resident=(\d+) pcie=(\d+) cpu=(\d+)',log)
  counts=[sum(int(v[i]) for v in rows) for i in range(3)];summary['screens'][name]={'tasks':group,'routing_fractions':[v/sum(counts) for v in counts] if rows else None}
