 anon=[]
 for row in resources:
  values=[]
  for text in row.get('process_memory',{}).values():
   values += [int(v) for v in re.findall(r'^(?:RssAnon|RssShmem):\s+(\d+) kB',text,re.M)]
  anon.append(sum(values)*1024)
